import{_ as r,l as s,o as e,c as i,v as o,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"片上网络 NoC","description":"","frontmatter":{"title":"片上网络 NoC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/noc-topology.md","filePath":"cs/noc-topology.md","lastUpdated":1789023840000}'),h={name:"cs/noc-topology.md"};function m(_,a,f,u,E,T){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="片上网络-noc" tabindex="-1">片上网络 NoC <a class="header-anchor" href="#片上网络-noc" aria-label="Permalink to &quot;片上网络 NoC&quot;">​</a></h1><div class="epigraph"><p>核、cache slice 与内存控制器不再共享一条广播总线；包在路由器之间跳，带宽随链路数涨，延迟变成跳数与拥塞。</p><footer>—— 据 Dally and Towles, Principles and Practices of Interconnection Networks 整理</footer></div><p><a href="/cs/heterogeneous-soc">上一课</a> 把多种核放在同一硅上。<a href="/cs/directory-scalability">目录</a> 已经要求点对点。十几个以上节点时，总线与交叉开关的线长、仲裁都不可接受。本课不重讲 big.LITTLE 迁移。缺口是 <strong>NoC：片上包交换网络作为一致性事务的载体。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广播窥探假设人人听见。交叉开关面积 \\(O(n^2)\\)。缺口不是再加一个 Forward 态，而是<strong>用路由器 + 链路连接 tile：每 tile 有核、L1、L2 slice、路由器。一致性消息、DMA、I/O 都变成 flit。</strong></p><p><span class="marginnote">Dally–Towles：互连是一等公民。片上与片间原理相同，只是延迟与缓冲预算不同。拓扑下一课才选 mesh 或 fat-tree。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个 tile 一个路由器：输入缓冲、路由计算、虚通道、开关分配、链路口。消息：读请求、转发、作废、ack、数据。 homing：地址哈希到 slice，即目录 home。QoS：不同虚通道给延迟敏感的一致性 ack 与批量 DMA。</p>',8)),(e(),n(p,null,{default:t(()=>[d(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22%E6%A0%B8%20%2F%20L1%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%22%5D%0A%20%20R%20--%3E%20LNK%5B%22%E9%93%BE%E8%B7%AF%E5%88%B0%E9%82%BB%20tile%22%5D%0A%20%20R%20--%3E%20SLICE%5B%22%E6%9C%AC%20tile%20%E7%9A%84%20L2%2F%E7%9B%AE%E5%BD%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/mlp-memory-parallelism">MLP</a> 的 miss 现在排队在 NoC 里；热点 slice 造成热树。与 <a href="/cs/fence-cost">fence</a>：fence 等待的「可见」包括包到达 home 并完成 inv ack，跳数进入临界区代价。功耗：连线与路由器缓冲是多核能耗大头之一。</p><p>包优先级：作废 ack 比批量 DMA 更延迟敏感，否则锁的临界区被大块拷贝堵住。这就是虚通道与 QoS 在片上出现的原因，具体拓扑下一课才选。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选定 mesh 或 torus，下一课拓扑。死锁与维序路由再下一课。多 socket 用另一套物理层。</p><p>后课默认：片上一致性走包交换。链路怎么铺、直径多少，由拓扑决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NoC 用路由器连接 tile，一致性变成包。</li><li>带宽随链路扩展，延迟变跳数与拥塞。</li><li>mesh / torus / fat-tree 是下一课。</li><li>出处：Dally and Towles。</li></ul>',8))])}const C=r(h,[["render",m]]);export{B as __pageData,C as default};
